// Marco de Compliance y Destruccion Binaria (Paso 12 / Punto 8 de la rubrica).
// El audio nunca se escribe a disco ni a ninguna base de datos en todo el
// flujo -- vive solo en la memoria volatil de esta ejecucion (el binario de
// Telegram y el de ElevenLabs). Este nodo lo hace explicito: al llegar aca
// el mensaje ya se envio, y se descarta toda referencia binaria del item
// antes de que la ejecucion termine, para que no quede accesible ni siquiera
// en el log de ejecucion mas de lo necesario.
const { binary, ...jsonSinBinario } = $input.item;
return [{ json: { ...jsonSinBinario.json, audio_procesado: true, audio_destruido: true } }];

// Convierte el binario del audio a base64 en un paso aparte -- hacerlo
// directo dentro de la expresion del HTTP Request es fragil en n8n
// (el campo terminaba llegando vacio). Este patron es mas confiable.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64String = buffer.toString('base64');
return [{ json: { ...$json, audio_base64: base64String } }];
